/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/**
 * The issue list filter vocabulary (ADR 0009). These spellings are the same in
 * the URL, in the request schema and in the repository.
 */

/** `assignee=me` / `author=me`: the signed-in user, resolved by the service. */
export const ME_TOKEN = "me" as const;

/** `assignee=none`: no assignee. */
export const UNASSIGNED_TOKEN = "none" as const;

/** Status groups usable wherever a status is: `open` is every status that is not closed. */
export const ISSUE_STATUS_GROUPS = {
  open: ISSUE_STATUSES.filter((status) => !CLOSED_ISSUE_STATUSES.includes(status)),
  closed: CLOSED_ISSUE_STATUSES,
} as const;

export type IssueStatusGroup = keyof typeof ISSUE_STATUS_GROUPS;
export type IssueStatusToken = IssueStatus | IssueStatusGroup;

export function isIssueStatusGroup(value: string): value is IssueStatusGroup {
  return Object.prototype.hasOwnProperty.call(ISSUE_STATUS_GROUPS, value);
}

export function isIssueStatusToken(value: string): value is IssueStatusToken {
  return (
    isIssueStatusGroup(value) ||
    (ISSUE_STATUSES as readonly string[]).includes(value)
  );
}

/**
 * Expands filter tokens to statuses. A group becomes its members wherever it
 * is read; each status appears once, in the order it is first named.
 */
export function expandIssueStatuses(
  tokens: readonly IssueStatusToken[],
): readonly IssueStatus[] {
  const statuses = new Set<IssueStatus>();
  for (const token of tokens) {
    const members = isIssueStatusGroup(token) ? ISSUE_STATUS_GROUPS[token] : [token];
    for (const status of members) statuses.add(status);
  }
  return [...statuses];
}

/**
 * A `due_before` value: a calendar day includes that whole day (UTC), a full
 * timestamp matches issues due strictly before that instant (ADR 0009 §5).
 */
export type DueBefore = IsoTimestamp | CalendarDate;

export type IssuePriority

