  orgId: orgIdSchema,
  issueId: issueIdSchema,
  title: z.string().min(3).max(200).optional(),
  description: z.string().max(20_000).nullable().optional(),
  priority: issuePrioritySchema.optional(),
  estimate: z.number().int().min(0).max(100).nullable().optional(),
  dueAt: isoTimestampSchema.nullable().optional(),
  labelIds: z.array(labelIdSchema).max(20).optional(),
});

export const changeIssueStatusSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  status: issueStatusSchema,
});

export const assignIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  assigneeId: userIdSchema.nullable(),
});

export const archiveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
});

/** A status, or one of the groups `open` / `closed` (ADR 0009 §3). */
export const issueStatusTokenSchema = z.union([
  issueStatusSchema,
  z.enum(["open", "closed"]),
]);

/** `assignee`: a user id, `me`, or `none` for unassigned (`null` too). */
const assigneeFilterSchema = z.union([
  userIdSchema,
  z.literal(ME_TOKEN),
  z.literal(UNASSIGNED_TOKEN).transform(() => null),
  z.null(),
]);

/**
 * `due_before`: a calendar day, which includes the whole day, or a full
 * ISO-8601 timestamp, which matches issues due strictly before it (ADR 0009 §5).
 */
export const dueBeforeSchema = z.union([
  z
    .string()
    .refine(isCalendarDate, "must be a real calendar date (YYYY-MM-DD)")
    .transform((value) => value as CalendarDate),
  z.iso
    .datetime({ offset: true })
    .transform((value) => toIsoTimestamp(value)),
]);

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z
      .array(issueStatusTokenSchema)
      .transform((tokens) => expandIssueStatuses(tokens))
      .optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: assigneeFilterSchema.optional(),
    authorId: z.union([userIdSchema, z.literal(ME_TOKEN)]).optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: dueBeforeSchema.optional(),
    archivedOnly: z.boolean().optional(),
