import { issueFilterSchema } from "@/schemas/issue";
import { exportIssuesSchema } from "@/schemas/export";
import { orgPath, toSearchParams, withSearchParams } from "@/lib/url";
import { toggleStatus } from "@/components/domain/issue/issue-filter-bar";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueStatus } from "@/types/issue";
import type { LabelId, UserId } from "@/types/common";

const ORG = "01ARZ3NDEKTSV4RRFFQ69G5FAV";

let cleanup: () => void;
let t: Tenant;
let bugId: LabelId;
let regressionId: LabelId;
const byTitle = new Map<string, string>();

async function add(
  title: string,
  extra: {
    assigneeId?: UserId | null;
    dueAt?: string | null;
    status?: IssueStatus;
    labelIds?: LabelId[];
    archive?: boolean;
  } = {},
) {
  const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const base = issueInput(t.org.id, t.project.id, {
    title,
    assigneeId: extra.assigneeId ?? null,
    dueAt: extra.dueAt ?? null,
  });
  const issue = await issueRepo.insertIssue(
    {
      ...base,
      status: extra.status ?? "backlog",
      labelIds: extra.labelIds ?? [],
    },
    t.userIds.owner,
    number,
  );
  if (extra.archive === true) await issueRepo.archiveIssue(t.org.id, issue.id);
  byTitle.set(title, issue.id);
  return issue;
}

function titlesOf(ids: readonly string[]): string[] {
  const names = new Map([...byTitle].map(([title, id]) => [id, title]));
  return ids.map((id) => names.get(id) ?? id).sort();
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratch-vocab");

  bugId = (await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ef4444", description: null })).id;
  regressionId = (await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#f59e0b", description: null })).id;

  await add("A", { assigneeId: t.userIds.owner, dueAt: "2026-10-09T09:00:00.000Z", labelIds: [bugId, regressionId] });
  await add("B", { assigneeId: t.userIds.owner, dueAt: "2026-10-09T18:00:00.000Z", labelIds: [bugId] });
  await add("C", { dueAt: "2026-10-10T00:00:00.000Z" });
  await add("D", {});
  await add("E", { assigneeId: t.userIds.owner, dueAt: "2026-10-08T12:00:00.000Z", status: "done", archive: true });
  await add("F", { status: "in_progress", labelIds: [regressionId] });
});

afterAll(() => {
  cleanup();
});

describe("scratch: report 1 (assignee=me)", () => {
  it("codec keeps me, service resolves it to the acting user", async () => {
    expect(parseIssueFilterParams(new URLSearchParams("assignee=me")).assigneeId).toBe("me");
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, assigneeId: "me", limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A", "B"]);
    expect(page.total).toBe(2);
  });
});

describe("scratch: report 2 (unassigned)", () => {
  it("assignee=none lists only unassigned live issues", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("assignee=none"));
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, ...filter, limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["C", "D", "F"]);
    expect(page.total).toBe(3);
  });
});

describe("scratch: report 3 (all-of labels, count agrees)", () => {
  it("two labels match only issues carrying both", async () => {
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, labelIds: [bugId, regressionId], limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A"]);
    expect(page.total).toBe(1);
  });

  it("one label still matches every issue carrying it", async () => {
    const page = await issueRepo.listIssues({ orgId: t.org.id, labelIds: [bugId], limit: 100, cursor: null });
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A", "B"]);
    expect(page.total).toBe(2);
  });

  it("duplicate label ids do not break the all-of count", async () => {
    const page = await issueRepo.listIssues({ orgId: t.org.id, labelIds: [bugId, bugId], limit: 100, cursor: null });
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A", "B"]);
  });
});

describe("scratch: report 4 (due_before calendar day)", () => {
  it("a calendar day includes issues due any time that day, not the next", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("due_before=2026-10-09"));
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, ...filter, limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A", "B"]);
    expect(page.total).toBe(2);
  });

  it("a full timestamp stays strict", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("due_before=2026-10-09T18:00:00.000Z"));
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, ...filter, limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A"]);
  });

  it("schema accepts a date and refuses an impossible one", () => {
    expect(issueFilterSchema.safeParse({ orgId: ORG, dueBefore: "2026-10-09" }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: ORG, dueBefore: "2026-02-30" }).success).toBe(false);
    expect(parseIssueFilterParams(new URLSearchParams("due_before=2026-02-30")).dueBefore).toBeUndefined();
  });
});

describe("scratch: report 5 (status groups)", () => {
  it("status=open expands to the four open statuses through codec and schema", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("status=open"));
    expect(filter.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, status: ["open"], limit: 100 });
    expect(parsed.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["A", "B", "C", "D", "F"]);
    expect(page.total).toBe(5);
  });

  it("the repository also understands group names", async () => {
    const page = await issueRepo.listIssues({
      orgId: t.org.id,
      status: ["open"] as unknown as IssueStatus[],
      limit: 100,
      cursor: null,
    });
    expect(page.total).toBe(5);
  });

  it("status=closed picks the closed statuses", async () => {
    const page = await issueService.listIssues(
      t.actors.owner,
      issueFilterSchema.parse({ orgId: t.org.id, status: ["closed"], includeArchived: true, limit: 100 }),
    );
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["E"]);
  });

  it("the export schema accepts the same vocabulary", () => {
    const parsed = exportIssuesSchema.parse({
      orgId: t.org.id,
      format: "json",
      ...parseIssueFilterParams(new URLSearchParams("status=open&assignee=none&archived=only")),
    });
    expect(parsed.status).toHaveLength(4);
    expect(parsed.assigneeId).toBeNull();
    expect(parsed.archivedOnly).toBe(true);
  });

  it("toggleStatus turns a group on and off as a whole", () => {
    const on = toggleStatus({}, "open");
    expect(on.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(toggleStatus(on, "open")).toEqual({});
    expect(toggleStatus({ status: ["done"] }, "closed").status).toEqual(["done", "canceled"]);
  });
});

describe("scratch: report 6 (archived only)", () => {
  it("archived=only lists archived issues and nothing else", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("archived=only"));
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, ...filter, limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(titlesOf(page.items.map((i) => i.id))).toEqual(["E"]);
    expect(page.total).toBe(1);
  });

  it("archived=1 still mixes archived into the live list", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("archived=1"));
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, ...filter, limit: 100 });
    const page = await issueService.listIssues(t.actors.owner, parsed);
    expect(page.total).toBe(6);
  });

  it("round-trips through the codec", () => {
    const params = issueFilterToParams(parseIssueFilterParams(new URLSearchParams("archived=only&assignee=me&status=open")));
    expect(params).toEqual({ status: "backlog,todo,in_progress,in_review", assignee: "me", archived: "only" });
  });
});

describe("scratch: helpers", () => {
  it("toSearchParams keeps repeated keys", () => {
    expect(toSearchParams({ status: ["todo", "done"], q: "x", n: undefined }).getAll("status")).toEqual(["todo", "done"]);
  });

  it("the sidebar query is not path-encoded", () => {
    expect(withSearchParams(orgPath("acme", "issues"), { assignee: "me" })).toBe("/acme/issues?assignee=me");
  });
});

